// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ref) public {
        vm.assume(ref != address(0) && ref != address(this));
        // Call DrugDealer() as the CEO
        vm.prank(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        c.DrugDealer();
        // After DrugDealer(), seedMarket with some drugs
        c.seedMarket(1000);
        // Now call getFreeKilo() for a fresh address; it should not revert
        vm.prank(ref);
        bool reverted;
        try c.getFreeKilo() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted, "getFreeKilo() should succeed after seedMarket()");
    }
}

